INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('f2d163ee-dfc7-4d99-ac29-e96937cbaa92', 'A1', 'reading', '我叫美玲，今年十八歲。我家有四個人：爸爸、媽媽、姐姐和我。我爸爸是老師，我媽媽在醫院工作。我姐姐是大學生，她喜歡看書。我們的家不大，可是很溫暖。', 'wǒ jiào měi líng， jīn nián shí bā suì。 wǒ jiā yǒu sì gè rén ： bà ba 、 mā mā 、 jiě jie hé wǒ。 wǒ bà ba shì lǎo shī， wǒ mā mā zài yī yuàn gōng zuò。 wǒ jiě jiě shì dà xué shēng， tā xǐ huān kàn shū。 wǒ mén de jiā bú dà， kě shì hěn wēn nuǎn。', 'Tôi tên là Mỹ Linh, năm nay mười tám tuổi. Nhà tôi có bốn người: bố, mẹ, chị gái và tôi. Bố tôi là giáo viên, mẹ tôi làm việc ở bệnh viện. Chị tôi là sinh viên đại học, chị thích đọc sách. Nhà chúng tôi không lớn, nhưng rất ấm áp.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('f2d163ee-dfc7-4d99-ac29-e96937cbaa92', 0, '美玲的爸爸做什麼工作？', ARRAY['醫生', '老師', '學生', '老闆'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('f2d163ee-dfc7-4d99-ac29-e96937cbaa92', 1, '美玲家有幾個人？', ARRAY['三個', '四個', '五個', '六個'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('3b10f4aa-f86d-4b29-ab1f-51b68eae9032', 'A1', 'reading', '我的學校很大，學校裡有很多學生和老師。我每天八點上課，中午十二點吃午飯。我最喜歡的科目是中文，因為老師教得很有意思。下課以後，我常常跟朋友一起打球。', 'wǒ de xué xiào hěn dà， xué xiào lǐ yǒu hěn duō xué shēng hé lǎo shī。 wǒ měi tiān bā diǎn shàng kè， zhōng wǔ shí èr diǎn chī wǔ fàn。 wǒ zuì xǐ huān de kē mù shì zhōng wén， yīn wéi lǎo shī jiào dé hěn yǒu yì sī。 xià kè yǐ hòu， wǒ cháng cháng gēn péng yǒu yì qǐ dǎ qiú。', 'Trường tôi rất lớn, trong trường có rất nhiều học sinh và giáo viên. Mỗi ngày tôi vào học lúc tám giờ, giữa trưa mười hai giờ ăn cơm trưa. Môn tôi thích nhất là tiếng Trung, vì thầy cô dạy rất thú vị. Sau giờ học, tôi thường cùng bạn chơi bóng.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('3b10f4aa-f86d-4b29-ab1f-51b68eae9032', 0, '我最喜歡的科目是什麼？', ARRAY['英文', '中文', '體育', '數學'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('3b10f4aa-f86d-4b29-ab1f-51b68eae9032', 1, '我幾點上課？', ARRAY['七點', '八點', '九點', '十點'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('da467b62-5f73-4b0f-94fc-fc3dafa41691', 'A1', 'reading', '今天天氣很好，太陽很大，可是不太熱。媽媽說明天會下雨，所以我今天要跟朋友去公園玩。公園裡有很多花，也有很多人在散步。', 'jīn tiān tiān qì hěn hǎo， tài yáng hěn dà， kě shì bú tài rè。 mā mā shuō míng tiān huì xià yǔ， suǒ yǐ wǒ jīn tiān yào gēn péng yǒu qù gōng yuán wán。 gōng yuán lǐ yǒu hěn duō huā， yě yǒu hěn duō rén zài sàn bù。', 'Hôm nay thời tiết rất đẹp, nắng to nhưng không quá nóng. Mẹ nói ngày mai sẽ mưa, nên hôm nay tôi định cùng bạn đi công viên chơi. Trong công viên có rất nhiều hoa, cũng có nhiều người đang đi dạo.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('da467b62-5f73-4b0f-94fc-fc3dafa41691', 0, '明天天氣怎麼樣？', ARRAY['很熱', '會下雨', '很冷', '有風'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('da467b62-5f73-4b0f-94fc-fc3dafa41691', 1, '我今天要去哪裡？', ARRAY['學校', '公園', '醫院', '家裡'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('0cb3b302-8871-4322-a1e3-7bc95315394a', 'A1', 'reading', '我每天早上七點起床，先刷牙洗臉，然後吃早飯。我通常吃麵包，喝牛奶。八點半我出門去學校。下午三點半放學以後，我回家做功課。晚上九點我就去睡覺了。', 'wǒ měi tiān zǎo shàng qī diǎn qǐ chuáng， xiān shuā yá xǐ liǎn， rán hòu chī zǎo fàn。 wǒ tōng cháng chī miàn bāo， hē niú nǎi。 bā diǎn bàn wǒ chū mén qù xué xiào。 xià wǔ sān diǎn bàn fàng xué yǐ hòu， wǒ huí jiā zuò gōng kè。 wǎn shàng jiǔ diǎn wǒ jiù qù shuì jué le。', 'Mỗi sáng tôi dậy lúc bảy giờ, trước tiên đánh răng rửa mặt, sau đó ăn sáng. Tôi thường ăn bánh mì, uống sữa. Tám giờ rưỡi tôi ra khỏi nhà đi học. Ba giờ rưỡi chiều tan học xong, tôi về nhà làm bài tập. Chín giờ tối tôi đi ngủ.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('0cb3b302-8871-4322-a1e3-7bc95315394a', 0, '我通常早餐吃什麼？', ARRAY['麵條', '麵包', '米飯', '餃子'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('0cb3b302-8871-4322-a1e3-7bc95315394a', 1, '我幾點出門去學校？', ARRAY['七點', '七點半', '八點半', '九點'], 2);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('cd7824df-6973-4a0c-b23d-db74e9fd9451', 'A1', 'reading', '我最喜歡吃的食物是餃子。媽媽常常在星期天做餃子給我們吃。餃子裡面有肉和青菜，非常好吃。我也喜歡喝熱茶，尤其是天氣冷的時候。', 'wǒ zuì xǐ huān chī de shí wù shì jiǎo zǐ。 mā mā cháng cháng zài xīng qī tiān zuò jiǎo zǐ gěi wǒ mén chī。 jiǎo zǐ lǐ miàn yǒu ròu hé qīng cài， fēi cháng hǎo chī。 wǒ yě xǐ huān hē rè chá， yóu qí shì tiān qì lěng de shí hòu。', 'Món ăn tôi thích nhất là sủi cảo. Mẹ thường làm sủi cảo cho chúng tôi ăn vào Chủ nhật. Trong sủi cảo có thịt và rau, rất ngon. Tôi cũng thích uống trà nóng, nhất là khi trời lạnh.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('cd7824df-6973-4a0c-b23d-db74e9fd9451', 0, '誰常常做餃子？', ARRAY['爸爸', '媽媽', '姐姐', '我'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('cd7824df-6973-4a0c-b23d-db74e9fd9451', 1, '媽媽通常什麼時候做餃子？', ARRAY['星期一', '星期三', '星期五', '星期天'], 3);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('3c1bb9f8-7df9-4ae1-8d69-3ebfae5aabfc', 'A1', 'reading', '我家在市中心，附近有一家小小的書店和一個公園。書店的老闆是一位很親切的爺爺。我常常星期六去書店看書，然後去公園散步。', 'wǒ jiā zài shì zhōng xīn， fù jìn yǒu yì jiā xiǎo xiǎo de shū diàn hé yí gè gōng yuán。 shū diàn de lǎo bǎn shì yí wèi hěn qīn qiè de yé yé。 wǒ cháng cháng xīng qī liù qù shū diàn kàn shū， rán hòu qù gōng yuán sàn bù。', 'Nhà tôi ở trung tâm thành phố, gần đó có một hiệu sách nhỏ và một công viên. Chủ hiệu sách là một ông cụ rất thân thiện. Tôi thường vào thứ Bảy đến hiệu sách đọc sách, sau đó đi dạo công viên.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('3c1bb9f8-7df9-4ae1-8d69-3ebfae5aabfc', 0, '書店的老闆是誰？', ARRAY['一位爺爺', '一位奶奶', '一位叔叔', '一位阿姨'], 0);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('3c1bb9f8-7df9-4ae1-8d69-3ebfae5aabfc', 1, '我常常星期幾去書店？', ARRAY['星期三', '星期五', '星期六', '星期日'], 2);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('c69b2e8f-575e-4138-9c3d-2fdb5cb88498', 'A1', 'listening', 'A：你好！我叫小華，你叫什麼名字？
B：你好，我叫美英。很高興認識你。
A：我也很高興認識你。你是學生嗎？
B：對，我是大學生。', 'A ： nǐ hǎo！ wǒ jiào xiǎo huá， nǐ jiào shén mó míng zì？ 
B ： nǐ hǎo， wǒ jiào měi yīng。 hěn gāo xīng rèn shí nǐ。 
A ： wǒ yě hěn gāo xīng rèn shí nǐ。 nǐ shì xué shēng má？ 
B ： duì， wǒ shì dà xué shēng。', 'A: Chào bạn! Mình tên là Tiểu Hoa, bạn tên gì? B: Chào bạn, mình tên Mỹ Anh. Rất vui được quen bạn. A: Mình cũng rất vui được quen bạn. Bạn là sinh viên phải không? B: Đúng vậy, mình là sinh viên đại học.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('c69b2e8f-575e-4138-9c3d-2fdb5cb88498', 0, '美英是做什麼的？', ARRAY['老師', '大學生', '醫生', '老闆'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('c69b2e8f-575e-4138-9c3d-2fdb5cb88498', 1, '誰先跟誰打招呼？', ARRAY['小華先跟美英打招呼', '美英先跟小華打招呼', '他們同時打招呼', '沒有人打招呼'], 0);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('5e5ba207-036e-4900-a501-0462194488b2', 'A1', 'listening', 'A：對不起，請問現在幾點？
B：現在是三點半。
A：謝謝你！我四點有課，快遲到了。
B：不客氣，你快去吧！', 'A ： duì bù qǐ， qǐng wèn xiàn zài jī diǎn？ 
B ： xiàn zài shì sān diǎn bàn。 
A ： xiè xiè nǐ！ wǒ sì diǎn yǒu kè， kuài chí dào le。 
B ： bú kè qì， nǐ kuài qù ba！', 'A: Xin lỗi, cho hỏi bây giờ mấy giờ rồi? B: Bây giờ là ba giờ rưỡi. A: Cảm ơn bạn! Bốn giờ mình có tiết học, sắp trễ rồi. B: Không có gì, bạn đi nhanh đi!');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('5e5ba207-036e-4900-a501-0462194488b2', 0, '現在是幾點？', ARRAY['兩點半', '三點半', '四點', '四點半'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('5e5ba207-036e-4900-a501-0462194488b2', 1, 'A為什麼很著急？', ARRAY['他肚子餓', '他四點有課', '他要回家', '他找不到書'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('a57f5c05-d0fd-4719-8eda-65756d7f0a86', 'A1', 'listening', 'A：老闆，我要買兩個麵包。
B：好的，一共是六十塊。
A：這是一百塊。
B：找你四十塊，謝謝光臨！', 'A ： lǎo bǎn， wǒ yào mǎi liǎng gè miàn bāo。 
B ： hǎo de， yí gòng shì liù shí kuài。 
A ： zhè shì yì bǎi kuài。 
B ： zhǎo nǐ sì shí kuài， xiè xiè guāng lín！', 'A: Chủ tiệm ơi, tôi muốn mua hai cái bánh mì. B: Được ạ, tổng cộng sáu mươi đồng. A: Đây là một trăm đồng. B: Trả lại bạn bốn mươi đồng, cảm ơn đã ghé mua!');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('a57f5c05-d0fd-4719-8eda-65756d7f0a86', 0, '顧客買了幾個麵包？', ARRAY['一個', '兩個', '三個', '四個'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('a57f5c05-d0fd-4719-8eda-65756d7f0a86', 1, '老闆找了多少錢？', ARRAY['二十塊', '三十塊', '四十塊', '五十塊'], 2);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('de04674c-a580-461d-b383-1a76ecb20fec', 'A1', 'listening', 'A：請問，圖書館怎麼走？
B：你往前走，然後在第二個路口右轉，圖書館就在你左邊。
A：要走很久嗎？
B：不會，大概五分鐘就到了。', 'A ： qǐng wèn， tú shū guǎn zěn mó zǒu？ 
B ： nǐ wǎng qián zǒu， rán hòu zài dì èr gè lù kǒu yòu zhuǎn， tú shū guǎn jiù zài nǐ zuǒ biān。 
A ： yào zǒu hěn jiǔ má？ 
B ： bú huì， dà gài wǔ fēn zhōng jiù dào le。', 'A: Xin hỏi, thư viện đi thế nào ạ? B: Bạn đi thẳng, sau đó ở ngã tư thứ hai rẽ phải, thư viện sẽ ở bên trái bạn. A: Có phải đi lâu không ạ? B: Không đâu, khoảng năm phút là tới.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('de04674c-a580-461d-b383-1a76ecb20fec', 0, '到圖書館大概要走多久？', ARRAY['兩分鐘', '五分鐘', '十分鐘', '半小時'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('de04674c-a580-461d-b383-1a76ecb20fec', 1, '圖書館在哪一邊？', ARRAY['右邊', '左邊', '對面', '後面'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('8e77de37-ca27-4972-8d1e-d6a6ca2394b5', 'A1', 'listening', 'A：喂，小明，你在做什麼？
B：我在家看書，你呢？
A：我在公園。你要不要一起來運動？
B：好啊，我馬上就去。', 'A ： wèi， xiǎo míng， nǐ zài zuò shén mó？ 
B ： wǒ zài jiā kàn shū， nǐ ne？ 
A ： wǒ zài gōng yuán。 nǐ yào bu yào yì qǐ lái yùn dòng？ 
B ： hǎo a， wǒ mǎ shàng jiù qù。', 'A: Alo, Tiểu Minh, cậu đang làm gì thế? B: Mình đang ở nhà đọc sách, còn cậu? A: Mình đang ở công viên. Cậu có muốn đến cùng tập thể dục không? B: Được đấy, mình đi ngay đây.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('8e77de37-ca27-4972-8d1e-d6a6ca2394b5', 0, '小明在做什麼？', ARRAY['看電視', '看書', '睡覺', '運動'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('8e77de37-ca27-4972-8d1e-d6a6ca2394b5', 1, 'A打電話約小明去哪裡？', ARRAY['圖書館', '公園', '學校', '餐廳'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('9b2c541e-743c-49ea-b205-02aad17ac8a9', 'A1', 'listening', 'A：媽媽，今天很冷嗎？
B：對啊，外面只有十度，你要穿外套。
A：好，那我也要戴帽子嗎？
B：對，風很大，戴帽子比較好。', 'A ： mā mā， jīn tiān hěn lěng má？ 
B ： duì a， wài miàn zhǐ yǒu shí dù， nǐ yào chuān wài tào。 
A ： hǎo， nà wǒ yě yào dài mào zi má？ 
B ： duì， fēng hěn dà， dài mào zi bǐ jiào hǎo。', 'A: Mẹ ơi, hôm nay có lạnh không ạ? B: Đúng vậy, ngoài trời chỉ có mười độ thôi, con phải mặc áo khoác. A: Vâng, vậy con có cần đội mũ không ạ? B: Có, gió to lắm, đội mũ thì tốt hơn.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('9b2c541e-743c-49ea-b205-02aad17ac8a9', 0, '外面現在幾度？', ARRAY['五度', '十度', '二十度', '三十度'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('9b2c541e-743c-49ea-b205-02aad17ac8a9', 1, '媽媽叫孩子戴帽子的原因是什麼？', ARRAY['太陽很大', '風很大', '要下雨', '天氣很熱'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('b4bdbfca-495b-47a8-bb30-0800e49be0ea', 'A2', 'reading', '這個週末我打算跟朋友一起去爬山。我們早上七點在捷運站集合，然後坐公車到山腳下。因為天氣預報說週末會出太陽，所以我們決定不改時間。爬完山以後，我們打算去附近的餐廳吃晚飯，慶祝朋友的生日。', 'zhè gè zhōu mò wǒ dǎ suàn gēn péng yǒu yì qǐ qù pá shān。 wǒ mén zǎo shàng qī diǎn zài jié yùn zhàn jí hé， rán hòu zuò gōng jū dào shān jiǎo xià。 yīn wéi tiān qì yù bào shuō zhōu mò huì chū tài yáng， suǒ yǐ wǒ mén jué dìng bù gǎi shí jiàn。 pá wán shān yǐ hòu， wǒ mén dǎ suàn qù fù jìn de cān tīng chī wǎn fàn， qìng zhù péng yǒu de shēng rì。', 'Cuối tuần này tôi dự định cùng bạn bè đi leo núi. Chúng tôi sẽ tập trung ở ga tàu điện ngầm lúc bảy giờ sáng, sau đó đi xe buýt đến chân núi. Vì dự báo thời tiết nói cuối tuần sẽ có nắng, nên chúng tôi quyết định không đổi thời gian. Sau khi leo núi xong, chúng tôi định đi ăn tối ở nhà hàng gần đó để chúc mừng sinh nhật của một người bạn.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('b4bdbfca-495b-47a8-bb30-0800e49be0ea', 0, '他們打算怎麼去山腳下？', ARRAY['走路', '坐公車', '騎腳踏車', '開車'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('b4bdbfca-495b-47a8-bb30-0800e49be0ea', 1, '爬山以後他們要做什麼？', ARRAY['回家睡覺', '去看電影', '去餐廳吃晚飯', '去買東西'], 2);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('6858db42-a49b-4623-9aaa-24e8f1e1ea11', 'A2', 'reading', '我在一家貿易公司工作已經兩年了。我的工作是跟外國客戶聯絡，有時候要用英文寫信，有時候要打電話。雖然工作有點忙，但是我覺得很有意思，因為我可以認識很多不同國家的人。', 'wǒ zài yì jiā mào yì gōng sī gōng zuò yǐ jīng liǎng nián le。 wǒ de gōng zuò shì gēn wài guó kè hù lián luò， yǒu shí hòu yào yòng yīng wén xiě xìn， yǒu shí hòu yào dǎ diàn huà。 suī rán gōng zuò yǒu diǎn máng， dàn shì wǒ jué dé hěn yǒu yì sī， yīn wéi wǒ kě yǐ rèn shí hěn duō bù tóng guó jiā de rén。', 'Tôi làm việc tại một công ty thương mại đã hai năm rồi. Công việc của tôi là liên lạc với khách hàng nước ngoài, có lúc phải viết thư bằng tiếng Anh, có lúc phải gọi điện thoại. Mặc dù công việc hơi bận, nhưng tôi thấy rất thú vị, vì tôi có thể quen biết nhiều người đến từ các quốc gia khác nhau.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('6858db42-a49b-4623-9aaa-24e8f1e1ea11', 0, '這個人在哪一種公司工作？', ARRAY['貿易公司', '醫院', '學校', '銀行'], 0);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('6858db42-a49b-4623-9aaa-24e8f1e1ea11', 1, '他覺得工作有意思的原因是什麼？', ARRAY['薪水很高', '可以認識不同國家的人', '工作很輕鬆', '可以常常出國'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('5cce73af-1cd7-491a-9562-2d1908c43d4e', 'A2', 'reading', '去年夏天我跟家人去台灣旅行了一個星期。我們去了台北和台南，吃了很多好吃的小吃，也參觀了幾個有名的博物館。台灣的夜市讓我印象最深刻，因為東西又便宜又好吃。', 'qù nián xià tiān wǒ gēn jiā rén qù tái wān lǚ xíng le yí gè xīng qī。 wǒ mén qù le tái běi hé tái nán， chī le hěn duō hǎo chī de xiǎo chī， yě cān guān le jī gè yǒu míng de bó wù guǎn。 tái wān de yè shì ràng wǒ yìn xiàng zuì shēn kè， yīn wéi dōng xī yòu pián yi yòu hǎo chī。', 'Mùa hè năm ngoái tôi cùng gia đình đi du lịch Đài Loan một tuần. Chúng tôi đã đến Đài Bắc và Đài Nam, ăn rất nhiều món ăn vặt ngon, cũng đã tham quan vài bảo tàng nổi tiếng. Chợ đêm ở Đài Loan để lại ấn tượng sâu sắc nhất với tôi, vì đồ ăn vừa rẻ vừa ngon.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('5cce73af-1cd7-491a-9562-2d1908c43d4e', 0, '這次旅行去了幾個星期？', ARRAY['一個星期', '兩個星期', '三個星期', '一個月'], 0);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('5cce73af-1cd7-491a-9562-2d1908c43d4e', 1, '什麼讓這個人印象最深刻？', ARRAY['博物館', '飛機場', '夜市', '飯店'], 2);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('2048f5b2-5118-4cd5-846b-a473ca860ba0', 'A2', 'reading', '昨天我開始頭痛、發燒，所以今天早上去看醫生了。醫生說我感冒了，叫我多休息、多喝水，還開了三天的藥。醫生說如果三天以後還是不舒服，就要再回去檢查。', 'zuó tiān wǒ kāi shǐ tóu tòng 、 fā shāo， suǒ yǐ jīn tiān zǎo shàng qù kàn yī shēng le。 yī shēng shuō wǒ gǎn mào le， jiào wǒ duō xiū xi 、 duō hē shuǐ， huán kāi le sān tiān de yào。 yī shēng shuō rú guǒ sān tiān yǐ hòu huán shì bù shū fú， jiù yào zài huí qù jiǎn chá。', 'Hôm qua tôi bắt đầu đau đầu, sốt, nên sáng nay đã đi khám bác sĩ. Bác sĩ nói tôi bị cảm, bảo tôi nghỉ ngơi nhiều, uống nhiều nước, còn kê thuốc uống trong ba ngày. Bác sĩ nói nếu sau ba ngày vẫn khó chịu thì phải quay lại khám lại.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('2048f5b2-5118-4cd5-846b-a473ca860ba0', 0, '醫生說這個人得了什麼病？', ARRAY['感冒', '肚子痛', '牙痛', '咳嗽'], 0);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('2048f5b2-5118-4cd5-846b-a473ca860ba0', 1, '醫生開了幾天的藥？', ARRAY['一天', '兩天', '三天', '一個星期'], 2);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('62e9afb9-9062-4548-88c8-81dc667399f7', 'A2', 'reading', '我從小就喜歡看書，尤其是關於歷史的書。我每個星期都會去圖書館借兩三本書，週末的時候常常一個人在家安靜地看一整天。除了看書以外，我也喜歡聽音樂，特別是古典音樂。', 'wǒ cóng xiǎo jiù xǐ huān kàn shū， yóu qí shì guān wū lì shǐ de shū。 wǒ měi gè xīng qī dōu huì qù tú shū guǎn jiè liǎng sān běn shū， zhōu mò de shí hòu cháng cháng yí gè rén zài jiā ān jìng dì kàn yì zhěng tiān。 chú le kàn shū yǐ wài， wǒ yě xǐ huān tīng yīn lè， tè bié shì gǔ diǎn yīn lè。', 'Từ nhỏ tôi đã thích đọc sách, đặc biệt là sách về lịch sử. Mỗi tuần tôi đều đến thư viện mượn hai ba cuốn sách, cuối tuần thường một mình ở nhà đọc yên tĩnh cả ngày. Ngoài đọc sách ra, tôi cũng thích nghe nhạc, đặc biệt là nhạc cổ điển.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('62e9afb9-9062-4548-88c8-81dc667399f7', 0, '這個人最喜歡看哪一種書？', ARRAY['歷史書', '小說', '漫畫', '雜誌'], 0);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('62e9afb9-9062-4548-88c8-81dc667399f7', 1, '這個人每星期去圖書館借幾本書？', ARRAY['一本', '兩三本', '四五本', '很多本'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('5111b286-1589-401b-acf3-de9bebf5a928', 'A2', 'reading', '這個星期百貨公司在辦週年慶，很多東西都打折。媽媽打算去買一台新的電視，因為家裡的電視已經用了十年了。妹妹想買衣服和鞋子，我則想買一些書。我們打算星期六一起去逛。', 'zhè gè xīng qī bǎi huò gōng sī zài bàn zhōu nián qìng， hěn duō dōng xī dōu dǎ zhé。 mā mā dǎ suàn qù mǎi yì tái xīn de diàn shì， yīn wéi jiā lǐ de diàn shì yǐ jīng yòng le shí nián le。 mèi mei xiǎng mǎi yī fú hé xié zǐ， wǒ zé xiǎng mǎi yì xiē shū。 wǒ mén dǎ suàn xīng qī liù yī qǐ qù guàng。', 'Tuần này trung tâm thương mại đang có đợt khuyến mãi kỷ niệm, rất nhiều thứ được giảm giá. Mẹ dự định mua một chiếc tivi mới, vì tivi ở nhà đã dùng mười năm rồi. Em gái muốn mua quần áo và giày, còn tôi thì muốn mua vài cuốn sách. Chúng tôi định cùng nhau đi dạo phố vào thứ Bảy.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('5111b286-1589-401b-acf3-de9bebf5a928', 0, '媽媽為什麼想買新電視？', ARRAY['舊電視壞了', '舊電視用了十年', '電視在打折', '妹妹想要'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('5111b286-1589-401b-acf3-de9bebf5a928', 1, '他們打算星期幾去百貨公司？', ARRAY['星期四', '星期五', '星期六', '星期日'], 2);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('b0b342e8-b0cf-49fb-a969-6d12d67cb51b', 'A2', 'listening', 'A：這個星期五你有空嗎？我們一起吃晚飯吧。
B：星期五我要加班，可能要八點才能到。
A：沒關係，那我們約八點半，在公司附近那家餐廳。
B：好，到時候見！', 'A ： zhè gè xīng qī wǔ nǐ yǒu kōng má？ wǒ mén yì qǐ chī wǎn fàn ba。 
B ： xīng qī wǔ wǒ yào jiā bān， kě néng yào bā diǎn cái néng dào。 
A ： méi guān xì， nà wǒ mén yuē bā diǎn bàn， zài gōng sī fù jìn nà jiā cān tīng。 
B ： hǎo， dào shí hòu jiàn！', 'A: Thứ Sáu tuần này bạn có rảnh không? Chúng ta cùng ăn tối nhé. B: Thứ Sáu mình phải làm thêm giờ, có lẽ tám giờ mới đến được. A: Không sao, vậy chúng ta hẹn tám giờ rưỡi, ở nhà hàng gần công ty đó. B: Được, lúc đó gặp nhau nhé!');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('b0b342e8-b0cf-49fb-a969-6d12d67cb51b', 0, '他們約在星期幾見面？', ARRAY['星期三', '星期四', '星期五', '星期六'], 2);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('b0b342e8-b0cf-49fb-a969-6d12d67cb51b', 1, 'B為什麼可能會晚到？', ARRAY['塞車', '要加班', '要接小孩', '身體不舒服'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('e4bd1a9d-6478-4a3e-861b-04adc5e07a40', 'A2', 'listening', 'A：請問去火車站要坐哪一班公車？
B：你可以坐二十三號，大概二十分鐘會到。
A：那我在哪一站下車呢？
B：到「中山路口」那一站下車就到了，司機會廣播的。', 'A ： qǐng wèn qù huǒ jū zhàn yào zuò nǎ yì bān gōng jū？ 
B ： nǐ kě yǐ zuò èr shí sān hào， dà gài èr shí fēn zhōng huì dào。 
A ： nà wǒ zài nǎ yí zhàn xià jū ne？ 
B ： dào 「zhōng shān lù kǒu」 nà yí zhàn xià jū jiù dào le， sī jī huì guǎng bō de。', 'A: Xin hỏi đi nhà ga xe lửa phải đi tuyến xe buýt nào? B: Bạn có thể đi tuyến hai mươi ba, khoảng hai mươi phút sẽ tới. A: Vậy tôi xuống ở trạm nào ạ? B: Xuống ở trạm ''Ngã tư đường Trung Sơn'' là tới, tài xế sẽ thông báo mà.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('e4bd1a9d-6478-4a3e-861b-04adc5e07a40', 0, '去火車站要坐幾號公車？', ARRAY['十三號', '二十號', '二十三號', '三十號'], 2);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('e4bd1a9d-6478-4a3e-861b-04adc5e07a40', 1, '大概要坐多久？', ARRAY['十分鐘', '二十分鐘', '三十分鐘', '一小時'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('745e56e2-2742-47ae-b2f3-2585eaade17a', 'A2', 'listening', 'A：您好，我想預約明天上午看牙醫。
B：好的，明天上午九點半還有一個時段，可以嗎？
A：可以，麻煩你了。
B：好，請問您貴姓大名？', 'A ： nín hǎo， wǒ xiǎng yù yuē míng tiān shàng wǔ kàn yá yī。 
B ： hǎo de， míng tiān shàng wǔ jiǔ diǎn bàn huán yǒu yí gè shí duàn， kě yǐ má？ 
A ： kě yǐ， má fán nǐ le。 
B ： hǎo， qǐng wèn nín guì xìng dà míng？', 'A: Xin chào, tôi muốn đặt hẹn khám răng vào sáng mai. B: Vâng, sáng mai lúc chín giờ rưỡi vẫn còn một khung giờ trống, được không ạ? A: Được ạ, phiền bạn giúp tôi. B: Vâng, xin hỏi quý danh của anh chị là gì ạ?');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('745e56e2-2742-47ae-b2f3-2585eaade17a', 0, '這通電話是要預約什麼？', ARRAY['看眼科', '看牙醫', '剪頭髮', '看內科'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('745e56e2-2742-47ae-b2f3-2585eaade17a', 1, '明天的時段是幾點？', ARRAY['八點半', '九點半', '十點半', '十一點半'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('2748c44f-59c3-4a64-a7d4-70cd751f417c', 'A2', 'listening', 'A：老闆，這件外套多少錢？
B：這件原價一千五，現在打八折，一千二就好。
A：可以再便宜一點嗎？
B：那我算你一千，不能再少了。', 'A ： lǎo bǎn， zhè jiàn wài tào duō shǎo qián？ 
B ： zhè jiàn yuán jià yì qiān wǔ， xiàn zài dǎ bā zhé， yì qiān èr jiù hǎo。 
A ： kě yǐ zài pián yi yì diǎn má？ 
B ： nà wǒ suàn nǐ yì qiān， bù néng zài shǎo le。', 'A: Chủ tiệm ơi, chiếc áo khoác này giá bao nhiêu? B: Chiếc này giá gốc một nghìn năm trăm, hiện đang giảm hai mươi phần trăm, một nghìn hai trăm thôi. A: Có thể rẻ hơn chút nữa không? B: Vậy tôi tính bạn một nghìn, không thể bớt thêm được nữa.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('2748c44f-59c3-4a64-a7d4-70cd751f417c', 0, '外套的原價是多少？', ARRAY['一千', '一千二', '一千五', '兩千'], 2);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('2748c44f-59c3-4a64-a7d4-70cd751f417c', 1, '最後老闆算顧客多少錢？', ARRAY['八百', '一千', '一千二', '一千五'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('4bae4aae-104e-479f-95d7-9f090a930947', 'A2', 'listening', 'A：暑假你有什麼計劃嗎？
B：我打算跟家人去日本玩十天，你呢？
A：我要留在家裡準備考試，沒辦法出去玩。
B：真可惜，等你考完試我們再一起出去玩吧。', 'A ： shǔ jiǎ nǐ yǒu shén mó jì huá má？ 
B ： wǒ dǎ suàn gēn jiā rén qù rì běn wán shí tiān， nǐ ne？ 
A ： wǒ yào liú zài jiā lǐ zhǔn bèi kǎo shì， méi bàn fǎ chū qù wán。 
B ： zhēn kě xī， děng nǐ kǎo wán shì wǒ mén zài yì qǐ chū qù wán ba。', 'A: Nghỉ hè bạn có kế hoạch gì không? B: Mình định cùng gia đình đi Nhật Bản chơi mười ngày, còn cậu? A: Mình phải ở nhà chuẩn bị thi, không thể đi chơi được. B: Tiếc thật, đợi cậu thi xong chúng ta lại cùng nhau đi chơi nhé.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('4bae4aae-104e-479f-95d7-9f090a930947', 0, 'B暑假打算去哪裡？', ARRAY['韓國', '日本', '泰國', '台灣'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('4bae4aae-104e-479f-95d7-9f090a930947', 1, 'A為什麼不能出去玩？', ARRAY['沒有錢', '要準備考試', '要工作', '身體不舒服'], 1);
INSERT INTO public.comprehension_passages (id, level, mode, passage_hanzi, passage_pinyin, passage_vietnamese) VALUES ('7cb1c132-ba32-4754-b4ca-821af5d98574', 'A2', 'listening', 'A：你平常幾點下班？
B：通常六點下班，可是這個月比較忙，常常要加班到八點。
A：那你回家以後還有時間運動嗎？
B：有時候有，我會去附近的公園跑步半個小時。', 'A ： nǐ píng cháng jī diǎn xià bān？ 
B ： tōng cháng liù diǎn xià bān， kě shì zhè gè yuè bǐ jiào máng， cháng cháng yào jiā bān dào bā diǎn。 
A ： nà nǐ huí jiā yǐ hòu huán yǒu shí jiàn yùn dòng má？ 
B ： yǒu shí hòu yǒu， wǒ huì qù fù jìn de gōng yuán pǎo bù bàn gè xiǎo shí。', 'A: Bình thường cậu mấy giờ tan làm? B: Thường thì sáu giờ tan làm, nhưng tháng này khá bận, hay phải làm thêm đến tám giờ. A: Vậy về nhà rồi cậu còn thời gian tập thể dục không? B: Thỉnh thoảng có, mình sẽ đi chạy bộ nửa tiếng ở công viên gần nhà.');
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('7cb1c132-ba32-4754-b4ca-821af5d98574', 0, '這個月B通常加班到幾點？', ARRAY['七點', '八點', '九點', '十點'], 1);
INSERT INTO public.comprehension_questions (passage_id, order_index, question_hanzi, options, correct_index) VALUES ('7cb1c132-ba32-4754-b4ca-821af5d98574', 1, 'B運動的方式是什麼？', ARRAY['游泳', '跑步', '打球', '騎腳踏車'], 1);